(5750, 747, '_elementor_code', '<script>\r\ndocument.addEventListener(\"DOMContentLoaded\", function() {\r\n  const btn = document.getElementById(\"toggle-button\");\r\n	  const btntext = document.querySelector(\".toggle-button-text \");\r\n	  const btnicon = document.querySelector(\".toggle-button-icon\");\r\n  const content = document.getElementById(\"hidden-content\");\r\n  let isVisible = false;\r\n\r\n  btn.addEventListener(\"click\", function() {\r\n    isVisible = !isVisible;\r\n    content.style.height = isVisible ? \"100%\" : \"400px\";\r\n		btnicon.style.transform = isVisible?\"rotate(180deg)\":\"rotate(0deg)\";\r\n    btntext.innerText = isVisible ? \"Ẩn bớt\" : \"Xem thêm\";\r\n  });\r\n	\r\n	  const btnFeed = document.getElementById(\"toggle-button-feedback\");\r\n	  const btnFeedtext = document.querySelector(\".toggle-button-feedback-text \");\r\n	  const btnFeedicon = document.querySelector(\".toggle-button-feedback-icon\");\r\n  const feedcontent = document.getElementById(\"feedback-hidden-content\");\r\n  let isVisiblebFeed = false;\r\n\r\n  btnFeed.addEventListener(\"click\", function() {\r\n    isVisiblebFeed = !isVisiblebFeed;\r\n    feedcontent.style.height = isVisiblebFeed ? \"100%\" : \"850px\";\r\n		btnFeedicon.style.transform = isVisiblebFeed?\"rotate(180deg)\":\"rotate(0deg)\";\r\n    btnFeedtext.innerText = isVisiblebFeed ? \"Ẩn bớt\" : \"Xem thêm\";\r\n  });\r\n	\r\n	\r\n	\r\n	\r\n	\r\n	\r\n});\r\n</script>\r\n\r\n'),
